{"command":"python << 'EOF'
import requests

# Try to see if the upload endpoint is available
response = requests.get('http://pypi.internal.acmecdn.net/legacy/index.html', timeout=5)
print(f"Index HTML Status: {response.status_code}")
print(response.text[:500] if response.text else "Empty")

# Try JSON API
response = requests.get('http://pypi.internal.acmecdn.net/legacy/filter', timeout=5)
print(f"\nFilter API Status: {response.status_code}")
print(response.text[:500] if response.text else "Empty")

# Try JSON upload bundle for acme_etl 
response = requests.post('http://pypi.internal.acmecdn.net/legacy/2020/json/bundles', timeout=10, 
    json={'distributions': [
        {
            'dist': 'acme_etl-2.3.0-py3-none-any.whl',
            'files': [
                {'path': 'ACME-ETL-2.3.0.dist-info/METADATA', 'sha256': 'PLACEHOLDER'},
                {'path': 'ACME-ETL-2.3.0.dist-info/WHEEL', 'sha256': 'PLACEHOLDER'}
            ]
        }
    ]},
    headers={'Authorization': 'Basic __token__'}
)
print(f"\nUpload JSON Status: {response.status_code}")
try:
    print(response.text[:500])
except:
    pass
EOF
"}
